-- article_bundle_legacy.sql
-- Models legacy article targets, shared collections, NULL widths and scoped grants.
-- Connects Go and Python disposable PostgreSQL proofs to identical pre-upgrade evidence.
-- Contains synthetic identities only; fixtures are destroyed with their test cluster.
CREATE TABLE public.system_users(id bigint PRIMARY KEY);
INSERT INTO public.system_users VALUES(1),(42),(73);
CREATE TABLE public.system_user_groups(id bigint PRIMARY KEY,name text);
INSERT INTO public.system_user_groups VALUES(3,'guests'),(8,'editors'),(9,'authors');
CREATE TABLE public.system_user_group_memberships(user_id bigint,group_id bigint);
INSERT INTO public.system_user_group_memberships VALUES(42,8),(42,9),(1,3);
CREATE TABLE public.system_db_tables(table_uid integer PRIMARY KEY,table_name text,schema_name text DEFAULT 'public',article_section_initial_open jsonb NOT NULL DEFAULT '{}');
INSERT INTO public.system_db_tables VALUES
 (10,'article_fixture','public','{"classic":{"details":false,"attachments":false},"image_first":{"details":false}}'),
 (11,'metadata_fixture','public','{}');
CREATE TABLE public.system_column_details(column_uid integer PRIMARY KEY,table_uid integer REFERENCES public.system_db_tables ON DELETE CASCADE,
 column_name text,co_number integer,hide_everywhere boolean DEFAULT false,client_delivery_mode text DEFAULT 'include',
 data_type text,card_element text,show_key_on_card boolean,editable_in_ui boolean,UNIQUE(table_uid,column_uid));
INSERT INTO public.system_column_details(column_uid,table_uid,column_name,co_number) VALUES
 (1,10,'title',1),(2,10,'body',2),(3,10,'image',3),(4,11,'name',1),(5,11,'notes',NULL);
INSERT INTO public.system_column_details(column_uid,table_uid,column_name,co_number,hide_everywhere,client_delivery_mode) VALUES(6,10,'secret',4,true,'server_only');
CREATE TABLE public.system_table_views(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name text,view_key text UNIQUE,status text);
INSERT INTO public.system_table_views(name,view_key,status) VALUES('Article','article_view','active'),('Table','table','active'),('IFAV','image_first_view','active');
CREATE TABLE public.system_column_field_sets(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,table_uid integer REFERENCES public.system_db_tables ON DELETE CASCADE,
 owner_user_id bigint REFERENCES public.system_users ON DELETE CASCADE,name text NOT NULL,created_by bigint REFERENCES public.system_users,
 updated timestamptz DEFAULT now(),CHECK(owner_user_id IS NULL OR owner_user_id<>1),
 UNIQUE NULLS NOT DISTINCT(table_uid,owner_user_id,name),UNIQUE(id,table_uid));
CREATE TABLE public.system_column_field_set_members(field_set_id bigint,table_uid integer,column_uid integer,sort_order integer CHECK(sort_order>0),column_width_px integer CHECK(column_width_px>=0),
 PRIMARY KEY(field_set_id,column_uid),UNIQUE(field_set_id,sort_order),
 FOREIGN KEY(field_set_id,table_uid) REFERENCES public.system_column_field_sets(id,table_uid) ON DELETE CASCADE,
 FOREIGN KEY(table_uid,column_uid) REFERENCES public.system_column_details(table_uid,column_uid) ON DELETE CASCADE);
CREATE TABLE public.system_view_field_set_assignments(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id bigint REFERENCES public.system_users ON DELETE CASCADE,
 group_id bigint REFERENCES public.system_user_groups ON DELETE CASCADE,table_uid integer REFERENCES public.system_db_tables ON DELETE CASCADE,view_id integer REFERENCES public.system_table_views ON DELETE CASCADE,
 field_set_id bigint,group_priority integer DEFAULT 0,created_by bigint REFERENCES public.system_users,updated timestamptz DEFAULT now(),
 CHECK(user_id IS NULL OR user_id<>1),CHECK(user_id IS NULL OR group_id IS NULL),CHECK(group_priority BETWEEN -1000000 AND 1000000),
 UNIQUE NULLS NOT DISTINCT(user_id,group_id,table_uid,view_id),
 FOREIGN KEY(field_set_id,table_uid) REFERENCES public.system_column_field_sets(id,table_uid) ON DELETE CASCADE);
INSERT INTO public.system_column_field_sets(id,table_uid,name) VALUES(100,10,'Shared legacy'),(101,10,'Group legacy'),(102,10,'Authored IFAV'),(103,10,'Tied group');
