CREATE TABLE public.system_functions(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name text UNIQUE,package text,disabled boolean DEFAULT false,specific_table_related boolean DEFAULT false,
 url_route_endpoint text,ui_only boolean,rate_limit_amount integer,rate_limit_minutes integer,creation_spec text);
INSERT INTO public.system_functions(name,url_route_endpoint) VALUES('ui.view.article_view','/ui/view/article_view'),('ui.view.image_first_view','/ui/view/image_first_view');
CREATE TABLE public.system_group_table_func_rights(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_group_id bigint REFERENCES public.system_user_groups,
 function_id bigint REFERENCES public.system_functions,target_schema_name text,target_table_uid integer REFERENCES public.system_db_tables,creation_spec text,
 UNIQUE(user_group_id,function_id,target_schema_name,target_table_uid));
