CREATE TABLE public.system_lang_keys(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,lang_key text UNIQUE,fi text,en text,ch text,yue text,creation_spec text);
CREATE TABLE public.system_lang_key_translations(lang_key_id bigint REFERENCES public.system_lang_keys,language_code text REFERENCES public.system_languages,
 translation text,source_kind text,review_status text,UNIQUE(lang_key_id,language_code));
